ve" }, { "id": "PHARM-000002", "category": "Pharmacology", "subcategory": "Antidotes", "difficulty": "hard", "question": "What is the specific reversal agent (antidote) for heparin-induced anticoagulation?", "options": [ "Protamine Sulfate", "Vitamin K (Phytonadione)", "Naloxone (Narcan)", "Flumazenil" ], "answer": 0, "explanation": "Protamine sulfate binds strongly to heparin to form an inactive salt complex. Vitamin K reverses Warfarin.", "tags": [ "pharmacology", "antidotes", "hematology", "heparin" ], "status": "active" }, { "id": "PHARM-000003", "category": "Pharmacology", "subcategory": "Analgesics", "difficulty": "easy", "question": "What is the specific emergency reversal medication administered for opioid overdose (respiratory depression)?", "options": [ "Naloxone (Narcan)", "Atropine", "Epinephrine", "Glucagon" ], "answer": 0, "explanation": "Naloxone is a pure opioid antagonist that rapidly displaces opioids from mu-receptors, reversing life-threatening respiratory depression.", "tags": [ "pharmacology", "emergency", "opioids", "naloxone" ], "status": "active" }, { "id": "SCI-000001", "category": "Science", "subcategory": "Physics", "difficulty": "medium", "question": "What is the speed of light in a vacuum (c)?", "options": [ "Approximately 300,000 km/s (299,792 km/s)", "Approximately 150,000 km/s", "Approximately 500,000 km/s", "343 m/s" ], "answer": 0, "explanation": "Light in a vacuum travels at 299,792,458 meters per second (approx 3.0 × 10^8 m/s).", "tags": [ "science", "physics", "light" ], "status": "active" }, { "id": "SCI-000002", "category": "Science", "subcategory": "Chemistry", "difficulty": "easy", "question": "What is the chemical symbol for Gold on the periodic table of elements?", "options": [ "Au", "Ag", "Fe", "Gd" ], "answer": 0, "explanation": "'Au' comes from the Latin word for gold, 'Aurum'.", "tags": [ "science", "chemistry", "periodic-table" ], "status": "active" }, { "id": "SCI-000003", "category": "Science", "subcategory": "Biology & Genetics", "difficulty": "hard", "question": "In molecular biology, which enzyme is responsible for synthesizing new DNA strands during replication by adding complementary nucleotides?", "options": [ "DNA Polymerase", "RNA Helicase", "DNA Ligase", "Topoisomerase" ], "answer": 0, "explanation": "DNA Polymerase synthesizes new DNA strands by matching complementary deoxynucleotides to the template strand in the 5' to 3' direction.", "tags": [ "science", "biology", "dna" ], "status": "active" }, { "id": "TECH-000001", "category": "Technology", "subcategory": "Internet", "difficulty": "easy", "question": "What does the abbreviation 'URL' stand for in web computing?", "options": [ "Uniform Resource Locator", "Universal Remote Link", "Unified Routing Language", "User Resource Lookup" ], "answer": 0, "explanation": "A URL (Uniform Resource Locator) specifies the web address of a resource on the internet.", "tags": [ "technology", "internet", "networking" ], "status": "active" }, { "id": "TECH-000002", "category": "Technology", "subcategory": "Artificial Intelligence", "difficulty": "medium", "question": "In Machine Learning, what does 'LLM' stand for?", "options": [ "Large Language Model", "Linear Logic Matrix", "Layered Learning Module", "Logical Link Mechanism" ], "answer": 0, "explanation": "Large Language Models (LLMs) are deep learning transformer models trained on vast text corpora.", "tags": [ "technology", "ai", "machine-learning" ], "status": "active" }, { "id": "TECH-000003", "category": "Technology", "subcategory": "Cybersecurity", "difficulty": "hard", "question": "In asymmetric cryptography, which key is used by a sender to encrypt a message so only the intended recipient can decrypt it?", "options": [ "The recipient's Public Key", "The sender's Private Key", "The recipient's Private Key", "The sender's Public Key" ], "answer": 0, "explanation": "In public-key cryptography (e.g. RSA), data encrypted with a recipient's public key can only be decrypted using