if (typeof module !== "undefined" && module.exports) { module.exports = { WKQUIZ_QUESTIONS }; } if (typeof window !== "undefined") { window.WKQUIZ_QUESTIONS = WKQUIZ_QUESTIONS; }
/* ========================================================================= */ /* 3. DATA PROVIDER ABSTRACTION LAYER */ /* ========================================================================= */ /** * WKQUIZ DATA PROVIDER LAYER * Abstraction layer between Quiz Engine and Question Bank. * Supports static JSON data, strict category + 3-difficulty filtering, * status filtering, and real-time accurate question count reporting. */
class WKQuizDataProvider { constructor(options = {}) { this.questions = []; this.categoriesMap = new Map(); this.byIdMap = new Map();
// Load initial question pool if (options.questions && Array.isArray(options.questions)) { this.loadQuestions(options.questions); } else if (typeof WKQUIZ_QUESTIONS !== "undefined" && Array.isArray(WKQUIZ_QUESTIONS)) { this.loadQuestions(WKQUIZ_QUESTIONS); } }
/** * Load or append questions into the provider */ loadQuestions(questionArray) { if (!Array.isArray(questionArray)) return;
questionArray.forEach(q => { if (!q || !q.id) return; this.questions.push(q); this.byIdMap.set(q.id, q);
const catKey = (q.category || "general").toLowerCase().trim(); if (!this.categoriesMap.has(catKey)) { this.categoriesMap.set(catKey, []); } this.categoriesMap.get(catKey).push(q); }); }
/** * Get single question by its permanent ID * @param {string} id - e.g. "NCLEX-000001" */ getQuestionById(id) { return this.byIdMap.get(id) || null; }
/** * Main query method used by Quiz Engine & UI Controller * @param {Object} options - { category, difficulty, length, status, mode } * @returns {Object} { questions: Array, totalAvailable: number, requestedLength: number, shortage: boolean, message: string } */ getQuestions(options = {}) { const category = (options.category || "all").toLowerCase().trim(); const difficulty = (options.difficulty || "all").toLowerCase().trim(); const requestedLength = options.length || 10; const requiredStatus = (options.status || "active").toLowerCase().trim();
// 1. Filter pool by category and status let pool = this.questions.filter(q => { // Status filter (strictly "active" for public gameplay) const qStatus = (q.status || "active").toLowerCase().trim(); if (qStatus !== requiredStatus) return false;
// Category filter if (category !== "all" && category !== "mixed-quiz") { const qCat = (q.category || "").toLowerCase().trim(); const inTags = q.tags && q.tags.map(t => t.toLowerCase()).includes(category); if (qCat !== category && !inTags) return false; }
return true; });
// 2. Strict Difficulty Filter (EASY | MEDIUM | HARD) — ZERO FALLBACK ACROSS DIFFICULTIES if (difficulty === "easy" || difficulty === "medium" || difficulty === "hard") { pool = pool.filter(q => (q.difficulty || "medium").toLowerCase().trim() === difficulty); }
const totalAvailable = pool.length; const shortage = totalAvailable < requestedLength; let message = "";
if (totalAvailable === 0) { message = `No active questions found for ${category.toUpperCase()} (${difficulty.toUpperCase()}).`; } else if (shortage) { message = `Only ${totalAvailable} unique ${difficulty.toUpperCase()} questions are currently available for this category.`; }
return { questions: pool, totalAvailable, requestedLength, shortage, message }; }
/** * Get exact active questions count for a specific category and difficulty * @param {string} category - Category slug or "all" * @param {string} difficulty - "easy" | "medium" | "hard" | "all" * @returns {number} Exact number of active questions */ getAvailableCount(category = "all", difficulty = "all") { const result = this.getQuestions({ category: category || "all", difficulty: difficulty || "all", length: 999999, status: "active" }); return result.totalAvailable; }
/** * Get category counts and difficulty breakdown */ getStats() { const stats = {}; this.questions.forEach(q => { const cat = (q.category || "General").trim(); const diff = (q.difficulty || "medium").toLowerCase().trim(); const status = (q.status || "active").toLowerCase().trim();
if (!stats[cat]) { stats[cat] = { easy: 0, medium: 0, hard: 0, active: 0, review: 0, draft: 0, disabled: 0, total: 0 }; }
stats[cat].total++; if (stats[cat][diff] !== undefined) stats[cat][diff]++; if (stats[cat][status] !== undefined) stats[cat][status]++; });
return stats; } }
// CommonJS export for Node.js test runners & browser window exposure if (typeof module !== "undefined" && module.exports) { module.exports = { WKQuizDataProvider }; } if (typeof window !== "undefined") { window.WKQuizDataProvider = WKQuizDataProvider; }
/* ========================================================================= */ /* 4. QUIZ ENGINE */ /* ========================================================================= */ /** * WKQUIZ ENGINE * Pure Vanilla JavaScript Quiz Engine. * Handles state management, unbiased Fisher-Yates shuffling with option remapping, * strict session duplicate prevention, timer, scoring, and deterministic Daily Quiz generator. * Decoupled from storage via Data Provider layer. */
class WKQuizEngine { constructor(options = {}) { this.config = Object.assign({ defaultLength: 10, availableLengths: [5, 10, 20, 50], availableDifficulties: ["easy", "medium", "hard"], timePerQuestionSeconds: 20, enableAnswerShuffle: true, enableQuestionShuffle: true, preventSessionDuplicates: true, passingScorePercentage: 70 }, options.config || (typeof WKQUIZ_CONFIG !== "undefined" ? WKQUIZ_CONFIG.quiz : {}));
// Data Provider interface if (options.provider) { this.provider = options.provider; } else if (typeof WKQuizDataProvider !== "undefined") { this.provider = new WKQuizDataProvider(); } else { this.provider = null; }
// Runtime state (initially null until a quiz is started) this.sessionUsedIds = new Set(); this.currentQuiz = null; this.currentIndex = 0; this.score = 0; this.streak = 0; this.maxStreak = 0; this.userAnswers = []; this.isCompleted = false; this.mode = null; this.category = null; this.difficulty = null; this.shortageNotice = ""; this.startTime = null; this.endTime = null;
// Timer variables this.timerInterval = null; this.timeRemaining = 0; this.onTick = null; this.onTimeExpired = null;
this._loadSessionStorage(); }
_loadSessionStorage() { if (typeof sessionStorage !== "undefined") { try { const stored = sessionStorage.getItem("wkquiz_used_ids"); if (stored) { const parsed = JSON.parse(stored); if (Array.isArray(parsed)) { parsed.forEach(id => this.sessionUsedIds.add(id)); } } } catch (e) {} } }
_saveSessionStorage() { if (typeof sessionStorage !== "undefined") { try { sessionStorage.setItem("wkquiz_used_ids", JSON.stringify([...this.sessionUsedIds])); } catch (e) {} } }
/** * Mulberry32 Deterministic PRNG for Daily Quiz */ _mulberry32(seed) { return function() { var t = seed += 0x6D2B79F5; t = Math.imul(t ^ t >>> 15, t | 1); t ^= t + Math.imul(t ^ t >>> 7, t | 61); return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
_hashString(str) { let hash = 0; for (let i = 0; i < str.length; i++) { const char = str.charCodeAt(i); hash = ((hash << 5) - hash) + char; hash |= 0; } return Math.abs(hash); }
/** * Standard Unbiased Fisher-Yates Array Shuffle */ _shuffleArray(array, customRng = Math.random) { const arr = [...array]; for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(customRng() * (i + 1)); [arr[i], arr[j]] = [arr[j], arr[i]]; } return arr; }
/** * Shuffle options of a question while preserving the exact correct answer pointer */ _shuffleQuestionOptions(question, customRng = Math.random) { const originalOptions = question.options; const correctOptionText = originalOptions[question.answer];
const indexed = originalOptions.map((text, idx) => ({ text, isCorrect: idx === question.answer })); const shuffled = this._shuffleArray(indexed, customRng);
const newOptions = shuffled.map(item => item.text); const newAnswerIndex = shuffled.findIndex(item => item.isCorrect);
return Object.assign({}, question, { options: newOptions, answer: newAnswerIndex, _originalAnswerText: correctOptionText }); }
/** * Prepare questions for a new quiz session * @param {Object} params - { category, difficulty, length, mode } */ startQuiz(params = {}) { const mode = params.mode || "classic"; const category = params.category || "all"; const difficulty = params.difficulty || "medium"; let length = params.length || this.config.defaultLength || 10;
if (mode === "quick") length = 5; else if (mode === "classic" && !params.length) length = 10; else if (mode === "challenge") length = 20; else if (mode === "exam") length = 50;
this.mode = mode; this.category = category; this.difficulty = difficulty; this.currentIndex = 0; this.score = 0; this.streak = 0; this.maxStreak = 0; this.userAnswers = []; this.isCompleted = false; this.shortageNotice = ""; this.startTime = Date.now(); this.endTime = null; this.stopTimer();
if (!this.provider) { throw new Error("No Data Provider configured for Quiz Engine"); }
let pool = [];
if (mode === "daily") { // Deterministic Daily Quiz based on today's UTC date const todayStr = new Date().toISOString().slice(0, 10); const seed = this._hashString("WKQUIZ_DAILY_" + todayStr); const rng = this._mulberry32(seed);
const queryResult = this.provider.getQuestions({ category: "all", difficulty: "all", status: "active" }); const allActive = queryResult.questions;
if (allActive.length === 0) { throw new Error("Question bank is empty"); }
const shuffledDaily = this._shuffleArray(allActive, rng); const selected = shuffledDaily.slice(0, Math.min(length, shuffledDaily.length));
pool = selected.map(q => this._shuffleQuestionOptions(q, rng)); } else { // Strict category + difficulty query (No Cross-Difficulty Fallback!) const queryResult = this.provider.getQuestions({ category, difficulty, length, status: "active" });
const available = queryResult.questions;
if (available.length === 0) { throw new Error(`No active questions available for "${category}" (${difficulty.toUpperCase()}).`); }
// Session duplicate prevention let candidatePool = available; if (this.config.preventSessionDuplicates) { const unused = available.filter(q => !this.sessionUsedIds.has(q.id)); if (unused.length >= length) { candidatePool = unused; } else if (unused.length > 0) { candidatePool = unused; this.sessionUsedIds.clear(); this._saveSessionStorage(); } else { this.sessionUsedIds.clear(); this._saveSessionStorage(); candidatePool = available; } }
// Shortage notice if pool has fewer questions than requested (NEVER DUPLICATE QUESTIONS!) if (candidatePool.length < length) { this.shortageNotice = `Note: Only ${candidatePool.length} active unique questions available for ${category.toUpperCase()} (${difficulty.toUpperCase()}).`; }
const shuffledQuestions = this.config.enableQuestionShuffle ? this._shuffleArray(candidatePool) : [...candidatePool];
const selected = shuffledQuestions.slice(0, Math.min(length, shuffledQuestions.length));
// Assert uniqueness const uniqueCheck = new Set(selected.map(q => q.id)); if (uniqueCheck.size !== selected.length) { throw new Error("Duplicate questions detected in quiz generation!"); }
selected.forEach(q => this.sessionUsedIds.add(q.id)); this._saveSessionStorage();
pool = selected.map(q => { return this.config.enableAnswerShuffle ? this._shuffleQuestionOptions(q) : Object.assign({}, q); }); }
this.currentQuiz = { id: `quiz_${Date.now()}`, mode, category, difficulty, requestedLength: length, totalQuestions: pool.length, shortageNotice: this.shortageNotice, questions: pool };
return this.getCurrentQuestion(); }
getCurrentQuestion() { if (!this.currentQuiz || this.currentIndex >= this.currentQuiz.questions.length) { return null; }
const q = this.currentQuiz.questions[this.currentIndex]; return { index: this.currentIndex, questionNumber: this.currentIndex + 1, totalQuestions: this.currentQuiz.totalQuestions, id: q.id, category: q.category, subcategory: q.subcategory || "", difficulty: q.difficulty || "medium", question: q.question, options: [...q.options], progressPercentage: Math.round(((this.currentIndex) / this.currentQuiz.totalQuestions) * 100), mode: this.mode, shortageNotice: this.shortageNotice }; }
submitAnswer(selectedOptionIndex) { if (!this.currentQuiz || this.isCompleted) { throw new Error("No active quiz in progress"); }
const currentQ = this.currentQuiz.questions[this.currentIndex]; const isCorrect = selectedOptionIndex === currentQ.answer;
if (isCorrect) { this.score++; this.streak++; if (this.streak > this.maxStreak) { this.maxStreak = this.streak; } } else { this.streak = 0; }
const answerRecord = { questionId: currentQ.id, questionText: currentQ.question, options: currentQ.options, selectedIndex: selectedOptionIndex, selectedOptionText: selectedOptionIndex !== null && selectedOptionIndex !== undefined ? currentQ.options[selectedOptionIndex] : "Timed Out / Skipped", correctIndex: currentQ.answer, correctOptionText: currentQ.options[currentQ.answer], isCorrect, explanation: currentQ.explanation || "No additional explanation provided." };
this.userAnswers.push(answerRecord);
const isSurvivalOver = (this.mode === "survival" && !isCorrect); const hasNext = (this.currentIndex + 1 < this.currentQuiz.totalQuestions) && !isSurvivalOver;
return { isCorrect, correctIndex: currentQ.answer, selectedIndex: selectedOptionIndex, explanation: currentQ.explanation || "No additional explanation provided.", score: this.score, streak: this.streak, hasNext, isSurvivalOver, questionNumber: this.currentIndex + 1, totalQuestions: this.currentQuiz.totalQuestions }; }
nextQuestion() { if (!this.currentQuiz) return null;
this.currentIndex++; if (this.currentIndex >= this.currentQuiz.totalQuestions) { this.finishQuiz(); return null; }
return this.getCurrentQuestion(); }
finishQuiz() { this.isCompleted = true; this.endTime = Date.now(); this.stopTimer();
const total = this.currentQuiz ? this.currentQuiz.totalQuestions : this.userAnswers.length; const percentage = total > 0 ? Math.round((this.score / total) * 100) : 0; const timeSpentSeconds = this.startTime ? Math.round((this.endTime - this.startTime) / 1000) : 0;
let badge = "Novice"; let message = "Good effort! Keep practicing to sharpen your knowledge.";
if (percentage === 100) { badge = "Grandmaster 🏆"; message = "Flawless victory! You scored 100% with absolute mastery."; } else if (percentage >= 90) { badge = "Expert 🌟"; message = "Outstanding performance! You possess elite subject knowledge."; } else if (percentage >= 75) { badge = "Scholar 🎓"; message = "Great job! You demonstrated solid understanding and skill."; } else if (percentage >= 50) { badge = "Apprentice 📖"; message = "Decent start! Review the explanations and challenge yourself again."; } else { badge = "Explorer 🧭"; message = "Every expert was once a beginner. Keep exploring and try again!"; }
return { quizId: this.currentQuiz ? this.currentQuiz.id : "", mode: this.mode, category: this.currentQuiz ? this.currentQuiz.category : "all", difficulty: this.difficulty, score: this.score, totalQuestions: total, percentage, passed: percentage >= this.config.passingScorePercentage, timeSpentSeconds, maxStreak: this.maxStreak, badge, message, answersSummary: [...this.userAnswers] }; }
startTimer(durationSeconds, onTick, onTimeExpired) { this.stopTimer(); this.timeRemaining = durationSeconds || this.config.timePerQuestionSeconds; this.onTick = onTick; this.onTimeExpired = onTimeExpired;
if (typeof this.onTick === "function") { this.onTick(this.timeRemaining); }
this.timerInterval = setInterval(() => { this.timeRemaining--; if (typeof this.onTick === "function") { this.onTick(this.timeRemaining); } if (this.timeRemaining <= 0) { this.stopTimer(); if (typeof this.onTimeExpired === "function") { this.onTimeExpired(); } } }, 1000); }
stopTimer() { if (this.timerInterval) { clearInterval(this.timerInterval); this.timerInterval = null; } }
getSharePayload(finalStats, siteUrl = "") { const stats = finalStats || this.finishQuiz(); const catName = stats.category ? stats.category.toUpperCase() : "WKQUIZ"; const text = `I scored ${stats.score}/${stats.totalQuestions} (${stats.percentage}%) on WKQuiz's ${catName} Challenge (${(stats.difficulty || 'MEDIUM').toUpperCase()})! Can you beat my score? 🧠🔥`; const shareUrl = siteUrl || (typeof window !== "undefined" ? window.location.href : "https://wkquiz.com");
return { text, url: shareUrl, whatsapp: `https://api.whatsapp.com/send?text=${encodeURIComponent(text + " " + shareUrl)}`, facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}&quote=${encodeURIComponent(text)}`, twitter: `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(shareUrl)}`, telegram: `https://t.me/share/url?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(text)}` }; } }
// CommonJS and Browser compatibility if (typeof module !== "undefined" && module.exports) { module.exports = { WKQuizEngine }; } if (typeof window !== "undefined") { window.WKQuizEngine = WKQuizEngine; }
/* ========================================================================= */ /* 5. UI CONTROLLER */ /* ========================================================================= */ /** * WKQUIZ UI CONTROLLER * Pure Vanilla JavaScript DOM Controller. * Handles category-first quiz flow: * STEP 1: Select Category -> STEP 2: Select Difficulty -> STEP 3: Select Question Count -> STEP 4: Play * Real-time data-aware question counts, zero fake numbers, zero question duplication. */
class WKQuizUI { constructor(engine, config) { this.engine = engine; this.config = config || (typeof WKQUIZ_CONFIG !== "undefined" ? WKQUIZ_CONFIG : {}); this.currentQuestionData = null; this.isAnswered = false;
// Current setup selection state (strictly null until category is selected) this.setupState = { category: null, difficulty: null, length: null };
this.dom = { container: document.getElementById("wk-quiz-container"), darkModeToggle: document.getElementById("wk-dark-toggle"), mobileMenuBtn: document.getElementById("wk-menu-btn"), mobileDrawer: document.getElementById("wk-mobile-drawer"), searchBtn: document.getElementById("wk-search-btn"), searchModal: document.getElementById("wk-search-modal"), searchInput: document.getElementById("wk-search-input"), searchResults: document.getElementById("wk-search-results"), searchClose: document.getElementById("wk-search-close"), categoriesContainer: document.getElementById("wk-categories-grid") };
this.init(); }
init() { this._initTheme(); this._initEvents(); this._renderCategoriesGrid();
// Check if query param exists (e.g. ?quiz=nclex) const hasParams = this._checkUrlParams(); if (!hasParams && this.dom.container) { // On initial page load: Show clean placeholder inviting category selection (NO premature difficulty screen) this._renderInitialCategoryPrompt(); } }
/** * Theme Management (Zero-flash Dark Mode) */ _initTheme() { const savedTheme = localStorage.getItem("wkquiz_theme"); const prefersDark = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches; const initialTheme = savedTheme || (prefersDark ? "dark" : (this.config.theme ? this.config.theme.defaultTheme : "light"));
document.documentElement.setAttribute("data-theme", initialTheme); if (document.body) document.body.setAttribute("data-theme", initialTheme); this._updateThemeIcon(initialTheme); }
toggleTheme() { const currentTheme = document.documentElement.getAttribute("data-theme") || "light"; const nextTheme = currentTheme === "dark" ? "light" : "dark"; document.documentElement.setAttribute("data-theme", nextTheme); if (document.body) document.body.setAttribute("data-theme", nextTheme); localStorage.setItem("wkquiz_theme", nextTheme); this._updateThemeIcon(nextTheme); }
_updateThemeIcon(theme) { if (this.dom.darkModeToggle) { this.dom.darkModeToggle.innerHTML = theme === "dark" ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>' : '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>'; } }
/** * Global Event Listeners */ _initEvents() { if (this.dom.darkModeToggle) { this.dom.darkModeToggle.addEventListener("click", () => this.toggleTheme()); }
if (this.dom.mobileMenuBtn && this.dom.mobileDrawer) { this.dom.mobileMenuBtn.addEventListener("click", () => { this.dom.mobileDrawer.classList.toggle("open"); }); }
if (this.dom.searchBtn && this.dom.searchModal) { this.dom.searchBtn.addEventListener("click", () => this.openSearch()); } if (this.dom.searchClose && this.dom.searchModal) { this.dom.searchClose.addEventListener("click", () => this.closeSearch()); } if (this.dom.searchModal) { this.dom.searchModal.addEventListener("click", (e) => { if (e.target === this.dom.searchModal) this.closeSearch(); }); } if (this.dom.searchInput) { this.dom.searchInput.addEventListener("input", (e) => this.handleSearch(e.target.value)); }
document.addEventListener("keydown", (e) => { if (e.key === "Escape" && this.dom.searchModal && this.dom.searchModal.classList.contains("open")) { this.closeSearch(); } if (e.key === "/" && document.activeElement.tagName !== "INPUT" && document.activeElement.tagName !== "TEXTAREA") { e.preventDefault(); this.openSearch(); } });
// Global CTA Handlers document.addEventListener("click", (e) => { const target = e.target.closest("[data-action]"); if (!target) return;
const action = target.getAttribute("data-action"); const category = target.getAttribute("data-category"); const mode = target.getAttribute("data-mode");
if (action === "select-category" || action === "open-setup" || action === "start-category") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); if (category) { this.renderSetupScreen(category, true); } else { this._scrollToCategories(); } } else if (action === "start-random") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); this.renderSetupScreen("mixed-quiz", true); } else if (action === "start-daily") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); this.startQuiz({ mode: "daily", category: "all" }, true); } else if (action === "start-mode") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); this.startQuiz({ mode: mode || "classic", category: category || "all" }, true); } else if (action === "restart-quiz") { e.preventDefault(); const lastCat = this.engine.currentQuiz ? this.engine.currentQuiz.category : "mixed-quiz"; this.renderSetupScreen(lastCat, true); } else if (action === "browse-categories") { e.preventDefault(); this._scrollToCategories(); } }); }
/** * Check URL query parameters on load (e.g. ?quiz=nclex) */ _checkUrlParams() { if (typeof window === "undefined" || !window.location.search) return false; const params = new URLSearchParams(window.location.search); const category = params.get("quiz") || params.get("category"); const difficulty = params.get("difficulty"); const length = parseInt(params.get("length"), 10); const mode = params.get("mode");
if (category || mode) { if (difficulty && length) { this.startQuiz({ category: category || "all", difficulty: difficulty || "medium", length: length || 10, mode: mode || "classic" }, true); } else { this.renderSetupScreen(category || "mixed-quiz", true); } return true; } return false; }
/** * Initial page load view: Prompt user to choose a category first */ _renderInitialCategoryPrompt() { if (!this.dom.container) return; this.dom.container.innerHTML = ` <div class="wk-setup-placeholder"> <span style="font-size: 2.2rem; display: block; margin-bottom: 0.5rem;">🎯</span> <h3 class="wk-setup-placeholder-title">Ready to Test Your Skills?</h3> <p class="wk-setup-placeholder-desc"> Choose any topic from our <strong>Browse Quiz Categories</strong> section below to customize your difficulty and question count. </p> <button type="button" class="wk-btn wk-btn-primary" data-action="browse-categories"> 📚 Browse Quiz Categories ➔ </button> </div> `; }
_scrollToCategories() { const catSection = document.getElementById("categories"); if (catSection) { catSection.scrollIntoView({ behavior: "smooth", block: "start" }); } }
/** * STEP 2 & 3: Render Quiz Customization Screen (Difficulty & Question Count) * User Flow: Category chosen -> Difficulty [Easy | Medium | Hard] -> Real Data-Aware Question Count -> Start */ renderSetupScreen(categoryId, shouldScroll = true) { if (!this.dom.container || !categoryId) return;
// 1. Establish Selected Category this.setupState.category = categoryId;
// Default difficulty to easy or medium if (!this.setupState.difficulty) { this.setupState.difficulty = "easy"; }
const cat = (this.config.categories || []).find(c => c.id === categoryId) || { id: categoryId, name: categoryId === "mixed-quiz" ? "Random Mixed Quiz" : categoryId.toUpperCase(), icon: categoryId === "mixed-quiz" ? "🎲" : "📚", description: "Test your knowledge across a curated set of questions." };
// 2. Query Real Active Pool for this exact Category + Difficulty const availableCount = this._getRealPoolCount(this.setupState.category, this.setupState.difficulty);
// 3. Determine available question count options const standardLengths = (this.config.quiz && this.config.quiz.availableLengths) || [5, 10, 20, 50];
// Auto-adjust selected length to a valid value if (!this.setupState.length || this.setupState.length > availableCount) { const validLengths = standardLengths.filter(len => len <= availableCount); if (validLengths.length > 0) { this.setupState.length = validLengths[validLengths.length - 1]; // pick highest available standard count } else if (availableCount > 0) { this.setupState.length = availableCount; // allow playing all available questions } else { this.setupState.length = 0; } }
let html = ` <div class="wk-quiz-card wk-setup-card"> <div class="wk-setup-header"> <span class="wk-badge wk-badge-primary" style="margin-bottom: 0.5rem; font-size: 0.85rem;"> ${cat.icon || "🎯"} ${cat.name.toUpperCase()} </span> <h2 class="wk-setup-title">Customize Your Quiz</h2> <p class="wk-setup-desc">${cat.description || "Select your preferred difficulty and number of questions to begin."}</p> </div>
<!-- 1. Difficulty Selector: Strictly Easy | Medium | Hard --> <div class="wk-setup-section"> <label class="wk-setup-label">1. Select Difficulty</label> <div class="wk-pills-grid" role="radiogroup" aria-label="Difficulty selection"> <button type="button" class="wk-pill-btn pill-easy ${this.setupState.difficulty === 'easy' ? 'active' : ''}" data-difficulty="easy"> <span>🟢 EASY</span> </button> <button type="button" class="wk-pill-btn pill-medium ${this.setupState.difficulty === 'medium' ? 'active' : ''}" data-difficulty="medium"> <span>🟡 MEDIUM</span> </button> <button type="button" class="wk-pill-btn pill-hard ${this.setupState.difficulty === 'hard' ? 'active' : ''}" data-difficulty="hard"> <span>🔴 HARD</span> </button> </div> </div>
<!-- 2. Question Count Selector (Data-Aware) --> <div class="wk-setup-section"> <label class="wk-setup-label">2. Select Question Count</label> <div class="wk-length-pills-grid" id="wk-length-pills" role="radiogroup" aria-label="Question count selection"> ${this._renderLengthButtonsHtml(standardLengths, availableCount)} </div> </div>
<!-- Real Question Pool Availability Notice --> <div id="wk-availability-box"> ${this._renderAvailabilityNoticeHtml(availableCount)} </div>
<!-- Start Quiz CTA --> <button type="button" id="wk-start-quiz-btn" class="wk-btn wk-btn-primary wk-btn-block" ${availableCount === 0 ? 'disabled' : ''}> 🚀 Start ${cat.name} Quiz ➔ </button> </div> `;
this.dom.container.innerHTML = html; this._bindSetupEvents();
if (shouldScroll) { this._scrollToQuiz(); } }
_getRealPoolCount(category, difficulty) { if (!this.engine || !this.engine.provider) return 0; return this.engine.provider.getAvailableCount(category, difficulty); }
_renderLengthButtonsHtml(standardLengths, availableCount) { let buttons = "";
standardLengths.forEach(len => { const isAvailable = len <= availableCount; const isSelected = this.setupState.length === len && isAvailable; const disabledAttr = isAvailable ? "" : "disabled"; const disabledClass = isAvailable ? "" : "disabled"; const activeClass = isSelected ? "active" : "";
buttons += ` <button type="button" class="wk-pill-btn ${activeClass} ${disabledClass}" data-length="${len}" ${disabledAttr} title="${isAvailable ? `${len} Questions` : `Needs at least ${len} questions (only ${availableCount} available)`}"> <span>${len} Questions</span> ${!isAvailable ? `<span style="font-size: 0.65rem; opacity: 0.8;">(Unavailable)</span>` : ''} </button> `; });
// If pool has fewer than 5 questions but > 0, offer a special custom count for all available questions if (availableCount > 0 && availableCount < 5) { const isCustomSelected = this.setupState.length === availableCount; buttons += ` <button type="button" class="wk-pill-btn ${isCustomSelected ? 'active' : ''}" data-length="${availableCount}" style="grid-column: span 2; border-color: var(--primary);"> <span>🎯 All ${availableCount} Available Questions</span> </button> `; }
return buttons; }
_renderAvailabilityNoticeHtml(availableCount) { const diffName = (this.setupState.difficulty || "medium").toUpperCase();
if (availableCount === 0) { return ` <div class="wk-setup-notice warning"> ⚠️ <strong>No active ${diffName} questions</strong> are currently available for this category. Please select another difficulty. </div> `; }
if (availableCount < 5) { return ` <div class="wk-setup-notice warning"> ⚠️ Only <strong>${availableCount} active ${diffName} questions</strong> are currently available in this pool. </div> `; }
return ` <div class="wk-setup-notice"> <span>📊 <strong>${availableCount} active unique ${diffName} questions</strong> ready in this pool</span> </div> `; }
_bindSetupEvents() { const container = this.dom.container; if (!container) return;
// Difficulty pill buttons const diffButtons = container.querySelectorAll("[data-difficulty]"); diffButtons.forEach(btn => { btn.addEventListener("click", () => { const newDiff = btn.getAttribute("data-difficulty"); this.setupState.difficulty = newDiff;
diffButtons.forEach(b => b.classList.remove("active")); btn.classList.add("active");
// Re-evaluate real pool count and update length buttons this._refreshAvailabilityAndLengths(); }); });
// Length pill buttons this._bindLengthButtons();
// Start Quiz button const startBtn = document.getElementById("wk-start-quiz-btn"); if (startBtn) { startBtn.addEventListener("click", () => { const available = this._getRealPoolCount(this.setupState.category, this.setupState.difficulty); if (available === 0) { alert("No questions available for this difficulty level. Please choose another difficulty."); return; }
const len = this.setupState.length || Math.min(10, available); this.startQuiz({ category: this.setupState.category, difficulty: this.setupState.difficulty, length: len, mode: "classic" }, true); }); } }
_bindLengthButtons() { const container = this.dom.container; if (!container) return;
const lenButtons = container.querySelectorAll("#wk-length-pills [data-length]"); lenButtons.forEach(btn => { btn.addEventListener("click", () => { if (btn.disabled || btn.classList.contains("disabled")) return; lenButtons.forEach(b => b.classList.remove("active")); btn.classList.add("active"); this.setupState.length = parseInt(btn.getAttribute("data-length"), 10); }); }); }
_refreshAvailabilityAndLengths() { const availableCount = this._getRealPoolCount(this.setupState.category, this.setupState.difficulty); const standardLengths = (this.config.quiz && this.config.quiz.availableLengths) || [5, 10, 20, 50];
// Adjust selected length if (!this.setupState.length || this.setupState.length > availableCount) { const validLengths = standardLengths.filter(len => len <= availableCount); if (validLengths.length > 0) { this.setupState.length = validLengths[validLengths.length - 1]; } else if (availableCount > 0) { this.setupState.length = availableCount; } else { this.setupState.length = 0; } }
// Update Length Pills Container const pillsContainer = document.getElementById("wk-length-pills"); if (pillsContainer) { pillsContainer.innerHTML = this._renderLengthButtonsHtml(standardLengths, availableCount); this._bindLengthButtons(); }
// Update Availability Notice Box const availBox = document.getElementById("wk-availability-box"); if (availBox) { availBox.innerHTML = this._renderAvailabilityNoticeHtml(availableCount); }
// Update Start Button Disabled State const startBtn = document.getElementById("wk-start-quiz-btn"); if (startBtn) { startBtn.disabled = (availableCount === 0); } }
/** * STEP 4: Start Quiz and Render Question Screen */ startQuiz(options = {}, shouldScroll = true) { if (!this.engine) return;
try { this.currentQuestionData = this.engine.startQuiz(options); this.isAnswered = false; this._renderQuizScreen(); if (shouldScroll) { this._scrollToQuiz(); } } catch (err) { console.error("[WKQuiz] Could not start quiz:", err); this._renderError(err.message || "Failed to load quiz."); } }
_scrollToQuiz() { if (this.dom.container) { this.dom.container.scrollIntoView({ behavior: "smooth", block: "start" }); } }
/** * Render Quiz Question Card */ _renderQuizScreen() { if (!this.dom.container || !this.currentQuestionData) return;
const q = this.currentQuestionData; const letters = ["A", "B", "C", "D", "E", "F"];
const categoryObj = (this.config.categories || []).find(c => c.id === q.category) || { name: (q.category || "General").toUpperCase(), icon: "🎯" };
const difficultyBadgeClass = q.difficulty === "hard" ? "wk-badge-danger" : (q.difficulty === "medium" ? "wk-badge-warning" : "wk-badge-success");
let html = ` <div class="wk-quiz-card" id="wk-active-card"> <div class="wk-quiz-header"> <div class="wk-quiz-meta"> <span class="wk-badge wk-badge-primary"> ${categoryObj.icon || "🎯"} ${categoryObj.name} </span> <span class="wk-badge ${difficultyBadgeClass}"> ${(q.difficulty || "medium").toUpperCase()} </span> <span class="wk-badge wk-badge-warning"> Question ${q.questionNumber} of ${q.totalQuestions} </span> ${q.mode === "daily" ? '<span class="wk-badge wk-badge-danger">🔥 Daily</span>' : ''} </div> <div id="wk-timer-badge" class="wk-quiz-timer" style="display: none;"> ⏱️ <span id="wk-timer-seconds">20</span>s </div> </div>
${q.shortageNotice ? `<div style="font-size: 0.8rem; color: var(--text-muted); margin-bottom: 0.75rem;">${this._escapeHtml(q.shortageNotice)}</div>` : ''}
<div class="wk-progress-bar-wrap" aria-label="Quiz progress"> <div class="wk-progress-bar-fill" style="width: ${q.progressPercentage}%;"></div> </div>
<h2 class="wk-question-text">${this._escapeHtml(q.question)}</h2>
<div class="wk-options-list" role="radiogroup" aria-label="Answer options"> ${q.options.map((opt, idx) => ` <button type="button" class="wk-option-btn" data-index="${idx}" role="radio" aria-checked="false"> <span class="wk-option-letter">${letters[idx] || (idx + 1)}</span> <span class="wk-option-label">${this._escapeHtml(opt)}</span> </button> `).join("")} </div>
<div class="wk-explanation-box" id="wk-explanation"> <div class="wk-explanation-title"> <span id="wk-expl-icon">💡</span> <span id="wk-expl-heading">Explanation</span> </div> <div class="wk-explanation-text" id="wk-expl-text"></div> </div>
<div class="wk-quiz-actions"> <button type="button" id="wk-next-btn" class="wk-btn wk-btn-primary" style="display: none;"> ${q.questionNumber === q.totalQuestions ? "View Final Results 🏆" : "Next Question ➔"} </button> </div> </div> `;
this.dom.container.innerHTML = html; this._bindOptionClicks();
// Start timer if mode is timed or config enables it if (q.mode === "timed" || (this.config.quiz && this.config.quiz.enableTimerByDefault)) { const timerBadge = document.getElementById("wk-timer-badge"); const timerSeconds = document.getElementById("wk-timer-seconds"); if (timerBadge && timerSeconds) { timerBadge.style.display = "inline-flex"; this.engine.startTimer( this.config.quiz.timePerQuestionSeconds || 20, (secs) => { timerSeconds.textContent = secs; if (secs <= 5) timerBadge.classList.add("urgent"); else timerBadge.classList.remove("urgent"); }, () => { if (!this.isAnswered) { this._handleAnswerSelect(null); } } ); } } }
_bindOptionClicks() { const card = document.getElementById("wk-active-card"); if (!card) return;
const optionBtns = card.querySelectorAll(".wk-option-btn"); optionBtns.forEach(btn => { btn.addEventListener("click", () => { if (this.isAnswered) return; const index = parseInt(btn.getAttribute("data-index"), 10); this._handleAnswerSelect(index); }); });
const nextBtn = document.getElementById("wk-next-btn"); if (nextBtn) { nextBtn.addEventListener("click", () => { this.engine.stopTimer(); const nextQ = this.engine.nextQuestion(); if (nextQ) { this.currentQuestionData = nextQ; this.isAnswered = false; this._renderQuizScreen(); } else { this._renderResultsScreen(); } }); } }
_handleAnswerSelect(selectedIndex) { this.isAnswered = true; this.engine.stopTimer();
const result = this.engine.submitAnswer(selectedIndex); const card = document.getElementById("wk-active-card"); if (!card) return;
const optionBtns = card.querySelectorAll(".wk-option-btn"); optionBtns.forEach((btn, idx) => { btn.disabled = true; if (idx === result.correctIndex) { btn.classList.add("correct"); btn.setAttribute("aria-checked", "true"); } if (idx === result.selectedIndex && !result.isCorrect) { btn.classList.add("incorrect"); } });
// Show Explanation const explBox = document.getElementById("wk-explanation"); const explHeading = document.getElementById("wk-expl-heading"); const explText = document.getElementById("wk-expl-text"); const explIcon = document.getElementById("wk-expl-icon");
if (explBox && explText) { explIcon.textContent = result.isCorrect ? "✅" : "❌"; explHeading.textContent = result.isCorrect ? "Correct! Well Done" : "Incorrect"; explText.textContent = result.explanation; explBox.classList.add("visible"); }
// Show Next or Results button const nextBtn = document.getElementById("wk-next-btn"); if (nextBtn) { nextBtn.style.display = "inline-flex"; if (result.isSurvivalOver) { nextBtn.textContent = "Game Over - View Results 💀"; } else if (!result.hasNext) { nextBtn.textContent = "View Final Results 🏆"; } } }
/** * Render Results Screen */ _renderResultsScreen() { if (!this.dom.container) return;
const stats = this.engine.finishQuiz(); const sharePayload = this.engine.getSharePayload(stats);
let html = ` <div class="wk-quiz-card wk-results-card"> <div class="wk-results-badge">${stats.badge}</div> <h2 class="wk-section-title" style="justify-content: center;">Quiz Completed!</h2>
<div class="wk-score-circle"> <div class="wk-score-number">${stats.score}/${stats.totalQuestions}</div> <div class="wk-score-percent">${stats.percentage}% Accuracy</div> </div>
<p class="wk-results-msg">${stats.message}</p>
<div class="wk-results-buttons"> <button type="button" class="wk-btn wk-btn-primary" data-action="restart-quiz"> 🔄 New Quiz / Retry </button> <button type="button" class="wk-btn wk-btn-secondary" data-action="start-random"> 🎲 Random Quiz </button> <button type="button" class="wk-btn wk-btn-secondary" data-action="start-daily"> 🔥 Daily Challenge </button> </div>
<!-- Social Viral Sharing --> <div class="wk-share-section"> <div class="wk-share-title">Challenge Your Friends</div> <div class="wk-share-grid"> <a href="${sharePayload.whatsapp}" target="_blank" rel="noopener noreferrer" class="wk-share-btn wk-share-whatsapp"> 📱 WhatsApp </a> <a href="${sharePayload.facebook}" target="_blank" rel="noopener noreferrer" class="wk-share-btn wk-share-facebook"> 📘 Facebook </a> <a href="${sharePayload.twitter}" target="_blank" rel="noopener noreferrer" class="wk-share-btn wk-share-twitter"> ✖️ Share on X </a> <button type="button" id="wk-copy-score-btn" class="wk-share-btn wk-share-copy"> 🔗 Copy Link </button> </div> </div> </div> `;
this.dom.container.innerHTML = html; this._bindShareButtons(sharePayload); this._scrollToQuiz(); }
_bindShareButtons(sharePayload) { const copyBtn = document.getElementById("wk-copy-score-btn"); if (copyBtn) { copyBtn.addEventListener("click", () => { if (navigator.clipboard) { navigator.clipboard.writeText(`${sharePayload.text}\n${sharePayload.url}`).then(() => { copyBtn.textContent = "✅ Link Copied!"; setTimeout(() => { copyBtn.textContent = "🔗 Copy Link"; }, 2500); }).catch(() => { this._fallbackCopyText(`${sharePayload.text}\n${sharePayload.url}`); }); } else { this._fallbackCopyText(`${sharePayload.text}\n${sharePayload.url}`); } }); } }
_fallbackCopyText(text) { const tempInput = document.createElement("textarea"); tempInput.value = text; document.body.appendChild(tempInput); tempInput.select(); document.execCommand("copy"); document.body.removeChild(tempInput); alert("Score copied to clipboard! Share it with your friends."); }
/** * STEP 1: Render Categories Grid on Homepage */ _renderCategoriesGrid() { if (!this.dom.categoriesContainer || !this.config.categories) return;
const categories = this.config.categories; const html = categories.map(cat => ` <a href="javascript:void(0)" class="wk-category-card" data-action="select-category" data-category="${cat.id}"> <span class="wk-category-icon">${cat.icon || "📚"}</span> <span class="wk-category-name">${cat.name}</span> <span class="wk-category-count">Select Category ➔</span> </a> `).join("");
this.dom.categoriesContainer.innerHTML = html; }
/** * Instant Search Modal Controls */ openSearch() { if (!this.dom.searchModal) return; this.dom.searchModal.classList.add("open"); if (this.dom.searchInput) { this.dom.searchInput.value = ""; this.dom.searchInput.focus(); this.handleSearch(""); } }
closeSearch() { if (!this.dom.searchModal) return; this.dom.searchModal.classList.remove("open"); }
handleSearch(query) { if (!this.dom.searchResults) return;
const term = (query || "").toLowerCase().trim(); const categories = this.config.categories || [];
const matched = categories.filter(c => c.name.toLowerCase().includes(term) || c.description.toLowerCase().includes(term) || c.slug.toLowerCase().includes(term) );
if (matched.length === 0) { this.dom.searchResults.innerHTML = ` <div style="padding: 1.5rem; text-align: center; color: var(--text-muted);"> No quizzes found matching "<strong>${this._escapeHtml(query)}</strong>". Try searching for <em>NCLEX</em>, <em>HVAC</em>, <em>Electrical</em>, or <em>Medical</em>. </div> `; return; }
const html = matched.map(cat => ` <a href="javascript:void(0)" class="wk-search-item" data-action="select-category" data-category="${cat.id}"> <span style="font-size: 1.5rem;">${cat.icon || "📚"}</span> <div> <div style="font-weight: 700;">${cat.name} Quiz</div> <div style="font-size: 0.8rem; color: var(--text-muted);">${cat.description}</div> </div> </a> `).join("");
this.dom.searchResults.innerHTML = html;
const items = this.dom.searchResults.querySelectorAll(".wk-search-item"); items.forEach(item => { item.addEventListener("click", () => { const catId = item.getAttribute("data-category"); this.closeSearch(); this.renderSetupScreen(catId, true); }); }); }
_renderError(message) { if (!this.dom.container) return; this.dom.container.innerHTML = ` <div class="wk-quiz-card" style="text-align: center; border-color: var(--danger);"> <h3 style="color: var(--danger); margin-bottom: 0.5rem;">⚠️ Notice</h3> <p style="color: var(--text-muted); margin-bottom: 1.5rem;">${this._escapeHtml(message)}</p> <button type="button" class="wk-btn wk-btn-primary" data-action="browse-categories"> Browse Categories </button> </div> `; }
_escapeHtml(str) { if (typeof str !== "string") return ""; return str .replace(/&/g, "&amp;") .replace(/</g, "&lt;") .replace(/>/g, "&gt;") .replace(/"/g, "&quot;") .replace(/'/g, "&#039;"); } }
// CommonJS and Browser compatibility if (typeof module !== "undefined" && module.exports) { module.exports = { WKQuizUI }; } if (typeof window !== "undefined") { window.WKQuizUI = WKQuizUI; }
/* ========================================================================= */ /* 6. AUTO-INITIALIZE PLATFORM ON LOAD */ /* ========================================================================= */ (function() { function initWKQuizPlatform() { if (window.__wkQuizInitialized) return; window.__wkQuizInitialized = true; try { if (typeof WKQuizEngine !== 'undefined' && typeof WKQuizUI !== 'undefined') { var provider = new WKQuizDataProvider({ questions: (typeof WKQUIZ_QUESTIONS !== 'undefined') ? WKQUIZ_QUESTIONS : [] }); var cfg = (typeof WKQUIZ_CONFIG !== 'undefined' && WKQUIZ_CONFIG) ? WKQUIZ_CONFIG : {}; var engine = new WKQuizEngine({ provider: provider, config: cfg.quiz || {} }); window.wkQuizProvider = provider; window.wkQuizEngine = engine; window.wkQuizApp = new WKQuizUI(engine, cfg); console.log('[WKQuiz] Platform successfully initialized.'); } } catch (e) { console.error('[WKQuiz] Initialization error:', e); } }
if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', initWKQuizPlatform); } else { initWKQuizPlatform(); } })(); //
